import os
from google.cloud import speech

def get_speech_client():
    """Provides a Google Cloud Speech-to-Text client."""
    return speech.SpeechClient()

def get_streaming_config(language_code: str, sample_rate_hertz: int, enable_automatic_punctuation: bool = False):
    """
    Returns a Google Cloud Speech-to-Text streaming recognition configuration.
    """
    return speech.StreamingRecognitionConfig(
        config=speech.RecognitionConfig(
            encoding=speech.RecognitionConfig.AudioEncoding.LINEAR16,
            sample_rate_hertz=sample_rate_hertz,
            language_code=language_code,
            enable_automatic_punctuation=enable_automatic_punctuation,
        ),
        interim_results=True,
    )

import json

class StreamingRecognitionResult:
    """Helper class to normalize streaming recognition results."""
    def __init__(self, response_json):
        self._response_json = response_json

    @property
    def transcript(self):
        for result in self._response_json.results:
            if result.alternatives:
                return result.alternatives[0].transcript
        return ""

    @property
    def is_final(self):
        for result in self._response_json.results:
            return result.is_final
        return False

    @property
    def confidence(self):
        for result in self._response_json.results:
            if result.alternatives:
                return result.alternatives[0].confidence
        return 0.0

    def to_dict(self):
        return {
            "text": self.transcript,
            "is_final": self.is_final,
            "confidence": self.confidence,
        }
